import{_ as e,o as n,c,a2 as h}from"./chunks/framework.62rcL0wY.js";const u=JSON.parse('{"title":"Tra cứu lệnh theo việc cần làm","description":"","frontmatter":{},"headers":[],"relativePath":"lenh/index.md","filePath":"lenh/index.md"}'),d={name:"lenh/index.md"};function i(a,t,o,r,l,m){return n(),c("div",null,[...t[0]||(t[0]=[h('<h1 id="tra-cuu-lenh-theo-viec-can-lam" tabindex="-1">Tra cứu lệnh theo việc cần làm <a class="header-anchor" href="#tra-cuu-lenh-theo-viec-can-lam" aria-label="Permalink to &quot;Tra cứu lệnh theo việc cần làm&quot;">​</a></h1><p>Trang này giúp bạn tìm nhanh câu lệnh Clickermann v4.13 theo nhu cầu thực tế (&quot;muốn làm việc X thì dùng lệnh nào&quot;), kèm liên kết trực tiếp tới mục tra cứu chi tiết của từng lệnh.</p><h2 id="cach-doc-mot-muc-lenh" tabindex="-1">Cách đọc một mục lệnh <a class="header-anchor" href="#cach-doc-mot-muc-lenh" aria-label="Permalink to &quot;Cách đọc một mục lệnh&quot;">​</a></h2><p>Trong các trang tra cứu lệnh chi tiết, mỗi mục lệnh đều được trình bày theo cùng một cấu trúc thống nhất:</p><ul><li><strong>Cặp ngoặc vuông <code>[ ]</code> trong cú pháp:</strong> Cho biết tham số đó là <strong>tùy chọn (không bắt buộc)</strong>. Nếu bạn bỏ qua không truyền, Clickermann sẽ tự dùng giá trị mặc định ghi trong bảng tham số (ví dụ với <code>WAITMS(500)</code> thì <code>500</code> là bắt buộc, còn với <code>INC($var, [value])</code> thì có thể viết gọn là <code>INC($var)</code>). <em>(Lưu ý: khi gõ lệnh thật vào script, bạn <strong>không</strong> gõ dấu ngoặc vuông <code>[ ]</code>).</em></li><li><strong>Dấu ba chấm <code>...</code> trong cú pháp:</strong> Cho biết bạn có thể truyền tiếp <strong>nhiều tham số không giới hạn số lượng</strong> ở phía sau, cách nhau bằng dấu phẩy (ví dụ <code>PRINT(&quot;A&quot;, $x, &quot;B&quot;)</code> hoặc <code>IF_PIXEL_IN(0, 0, 100, 100, 255, 65280)</code>).</li><li><strong>Loại lệnh:</strong><ul><li><strong>Thủ tục:</strong> Câu lệnh thực hiện một hành động và đứng riêng trên một dòng (ví dụ <code>LCLICK(100, 200)</code>).</li><li><strong>Hàm:</strong> Câu lệnh tính toán và <strong>trả về một giá trị</strong> ngay tại vị trí gọi nó để gán vào biến hoặc đặt bên trong biểu thức khác (ví dụ <code>$so = RND(1, 10)</code>).</li><li><strong>Cấu trúc lệnh:</strong> Khối lệnh gồm nhiều dòng, có dòng mở đầu và dòng từ khóa đóng khối (như <code>IF ... END_IF</code>, <code>FOR ... END_CYC</code>).</li></ul></li><li><strong>Trạng thái kiểm chứng:</strong> <code>🟡 Theo help, chưa chạy thử</code> (sát theo <code>help.chm</code> v4.13.014) hoặc <code>🟠 Chưa thống nhất</code> (có điểm khác biệt giữa các nguồn tài liệu, kèm hướng dẫn <strong>&quot;Nên làm&quot;</strong>).</li><li><strong>Trả về:</strong> Giá trị kết quả mà hàm trả về, hoặc các biến hệ thống (<code>$_return1</code>, <code>$_return2</code>) được lệnh cập nhật sau khi chạy.</li></ul><h2 id="nhom-trang-tra-cuu-lenh" tabindex="-1">Nhóm trang tra cứu lệnh <a class="header-anchor" href="#nhom-trang-tra-cuu-lenh" aria-label="Permalink to &quot;Nhóm trang tra cứu lệnh&quot;">​</a></h2><ul><li><a href="/clickermann-guide-vi/lenh/so.html">Số, biến và mảng</a> — Biến, toán học, lượng giác, làm tròn, số ngẫu nhiên và mảng.</li><li><a href="/clickermann-guide-vi/lenh/chuoi-file.html">Chuỗi, tệp tin, bộ nhớ tạm và HTTP</a> — Xử lý chuỗi, tệp <code>.ini</code>, tệp <code>.txt</code>, Clipboard và truy vấn HTTP.</li><li><a href="/clickermann-guide-vi/lenh/chuot.html">Chuột</a> — Bấm chuột trái/phải/giữa, nhấp đúp, kéo thả, di chuyển và cuộn chuột.</li><li><a href="/clickermann-guide-vi/lenh/ban-phim.html">Bàn phím</a> — Bấm phím, giữ phím, gõ chuỗi, kiểm tra phím đang nhấn và đổi kiểu bàn phím.</li><li><a href="/clickermann-guide-vi/lenh/cau-truc.html">Điều kiện, vòng lặp, chương trình con</a> — Cấu trúc rẽ nhánh <code>IF</code>, <code>SWITCH</code>, vòng lặp <code>FOR</code>, <code>WHILE</code>, <code>SUB</code> và đa luồng <code>THREAD</code>.</li><li><a href="/clickermann-guide-vi/lenh/man-hinh.html">Màn hình và màu sắc</a> — Chụp bộ đệm ảnh, đọc/tìm màu, tìm ảnh <code>.bmp</code>, giảm màu và lưu ảnh chụp.</li><li><a href="/clickermann-guide-vi/lenh/nhat-ky.html">Nhật ký và âm báo</a> — Ghi nhật ký, hiện/ẩn cửa sổ nhật ký, phát âm thanh <code>.wav</code>, tiếng bíp và thông báo ở khay hệ thống.</li><li><a href="/clickermann-guide-vi/lenh/kich-ban.html">Điều khiển script và hệ thống</a> — Tạm dừng chờ, nhảy nhãn, hộp thoại, gọi lệnh ngoài, nạp plugin DLL và quét thư mục.</li><li><a href="/clickermann-guide-vi/lenh/winapi.html">Cửa sổ và WinAPI</a> — Tìm cửa sổ, khóa cửa sổ, đổi vị trí/kích thước và gửi/nhận thông điệp Windows.</li></ul><hr><h2 id="lay-thong-tin-thuong-dung-gio-giac-toa-do-chuot-cho-mau" tabindex="-1">Lấy thông tin thường dùng (giờ giấc, tọa độ chuột, chờ màu) <a class="header-anchor" href="#lay-thong-tin-thuong-dung-gio-giac-toa-do-chuot-cho-mau" aria-label="Permalink to &quot;Lấy thông tin thường dùng (giờ giấc, tọa độ chuột, chờ màu)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc cần làm</th><th>Cách thực hiện trong Clickermann</th><th>Xem hướng dẫn</th></tr></thead><tbody><tr><td>Xem giờ, phút, giây hiện tại</td><td>Đọc các biến hệ thống <code>$_time_h</code> (giờ), <code>$_time_m</code> (phút), <code>$_time_s</code> (giây), <code>$_time_str</code> (chuỗi giờ)</td><td><a href="/clickermann-guide-vi/khai-niem/ngon-ngu.html#cac-bien-he-thong-hay-dung-nhat">Ngôn ngữ script</a>, <a href="/clickermann-guide-vi/cam-nang/click-theo-lich.html">Bấm chuột theo lịch</a></td></tr><tr><td>Xem ngày, tháng, năm hiện tại</td><td>Đọc các biến hệ thống <code>$_date_d</code>, <code>$_date_m</code>, <code>$_date_y</code>, <code>$_date_str</code></td><td><a href="/clickermann-guide-vi/khai-niem/ngon-ngu.html#bang-bien-he-thong-day-du">Bảng biến hệ thống</a></td></tr><tr><td>Xem vị trí con trỏ chuột hiện tại</td><td>Đọc hai biến hệ thống <code>$_xmouse</code> (X) và <code>$_ymouse</code> (Y)</td><td><a href="/clickermann-guide-vi/khai-niem/ngon-ngu.html#cac-bien-he-thong-hay-dung-nhat">Ngôn ngữ script</a></td></tr><tr><td>Đọc mã màu của 1 điểm trên màn hình</td><td>Gọi <a href="/clickermann-guide-vi/lenh/man-hinh.html#getscreen"><code>GETSCREEN</code></a> rồi gọi hàm <a href="/clickermann-guide-vi/lenh/man-hinh.html#pxl"><code>PXL(x, y)</code></a></td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#pxl">Màn hình và màu sắc</a></td></tr><tr><td>Chờ tới khi một màu xuất hiện trên màn hình</td><td>Đặt <a href="/clickermann-guide-vi/lenh/man-hinh.html#getscreen"><code>GETSCREEN</code></a> + <a href="/clickermann-guide-vi/lenh/man-hinh.html#if-pixel-in-end-if"><code>IF_PIXEL_IN</code></a> bên trong vòng lặp <a href="/clickermann-guide-vi/lenh/cau-truc.html#while-end-cyc"><code>WHILE ... END_CYC</code></a></td><td><a href="/clickermann-guide-vi/cam-nang/tim-mau.html#tinh-huong-2-cho-cho-toi-khi-mau-xuat-hien-roi-moi-di-tiep">Cẩm nang tìm màu</a></td></tr></tbody></table><hr><h2 id="thao-tac-chuot-va-ban-phim" tabindex="-1">Thao tác chuột và bàn phím <a class="header-anchor" href="#thao-tac-chuot-va-ban-phim" aria-label="Permalink to &quot;Thao tác chuột và bàn phím&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc cần làm</th><th>Lệnh nên dùng</th><th>Ghi chú nhanh</th></tr></thead><tbody><tr><td>Bấm chuột trái 1 lần</td><td><a href="/clickermann-guide-vi/lenh/chuot.html#lclick"><code>LCLICK</code></a></td><td>Đưa trỏ tới <code>(x, y)</code> rồi bấm trái</td></tr><tr><td>Nhấp đúp chuột trái</td><td><a href="/clickermann-guide-vi/lenh/chuot.html#dblclick"><code>DBLCLICK</code></a></td><td>Bấm đúp trái tại <code>(x, y)</code></td></tr><tr><td>Kéo thả chuột (drag &amp; drop)</td><td><a href="/clickermann-guide-vi/lenh/chuot.html#ldown"><code>LDOWN</code></a>, <a href="/clickermann-guide-vi/lenh/chuot.html#lup"><code>LUP</code></a></td><td>Nhấn giữ ở điểm đầu, chờ ngắn rồi nhả ở điểm đích</td></tr><tr><td>Bấm / giữ / nhả chuột phải</td><td><a href="/clickermann-guide-vi/lenh/chuot.html#rclick-rdown-rup"><code>RCLICK, RDOWN, RUP</code></a></td><td>Tương tự chuột trái nhưng cho nút phải</td></tr><tr><td>Bấm / giữ / nhả chuột giữa</td><td><a href="/clickermann-guide-vi/lenh/chuot.html#mclick-mdown-mup"><code>MCLICK, MDOWN, MUP</code></a></td><td>Tương tự chuột trái nhưng cho nút giữa</td></tr><tr><td>Di chuyển con trỏ tới tọa độ</td><td><a href="/clickermann-guide-vi/lenh/chuot.html#move"><code>MOVE</code></a></td><td>Chỉ đưa trỏ chuột tới <code>(x, y)</code>, không bấm</td></tr><tr><td>Dịch chuột tương đối</td><td><a href="/clickermann-guide-vi/lenh/chuot.html#mover"><code>MOVER</code></a></td><td>Không chạy ở chế độ khóa cửa sổ</td></tr><tr><td>Cuộn con lăn chuột xuống / lên</td><td><a href="/clickermann-guide-vi/lenh/chuot.html#wheeldown"><code>WHEELDOWN</code></a>, <a href="/clickermann-guide-vi/lenh/chuot.html#wheelup"><code>WHEELUP</code></a></td><td>Có hệ số nhân tốc độ cuộn <code>mult</code></td></tr><tr><td>Bấm 1 phím bàn phím</td><td><a href="/clickermann-guide-vi/lenh/ban-phim.html#keypress"><code>KEYPRESS</code></a></td><td>Truyền mã số hoặc hằng như <code>#SPACE</code></td></tr><tr><td>Nhấn giữ / nhả phím (tổ hợp phím)</td><td><a href="/clickermann-guide-vi/lenh/ban-phim.html#keydown"><code>KEYDOWN</code></a>, <a href="/clickermann-guide-vi/lenh/ban-phim.html#keyup"><code>KEYUP</code></a></td><td>Dùng để bấm tổ hợp như <code>Ctrl + S</code> (🟠 có trường hợp cần <a href="/clickermann-guide-vi/phu-luc/ma-phim.html#khi-keydown-can-ma-khac">mã khác <code>KEYPRESS</code></a>)</td></tr><tr><td>Gõ một chuỗi ký tự</td><td><a href="/clickermann-guide-vi/lenh/ban-phim.html#keystring"><code>KEYSTRING</code></a></td><td>Phụ thuộc bộ gõ; không bấm được phím không phải ký tự</td></tr><tr><td>Kiểm tra 1 phím có đang được nhấn</td><td><a href="/clickermann-guide-vi/lenh/ban-phim.html#iskeydown"><code>ISKEYDOWN</code></a></td><td>Kiểm tra được cả phím bàn phím và nút chuột</td></tr><tr><td>Lấy danh sách mọi phím đang nhấn</td><td><a href="/clickermann-guide-vi/lenh/ban-phim.html#getkeysdown"><code>GETKEYSDOWN</code></a></td><td>Đổ danh sách mã phím đang nhấn vào mảng</td></tr><tr><td>Xem / đổi ngôn ngữ bàn phím của cửa sổ</td><td><a href="/clickermann-guide-vi/lenh/ban-phim.html#getkblayout"><code>GETKBLAYOUT</code></a>, <a href="/clickermann-guide-vi/lenh/ban-phim.html#setkblayout"><code>SETKBLAYOUT</code></a></td><td>Làm việc theo <code>hwnd</code> của cửa sổ</td></tr></tbody></table><hr><h2 id="man-hinh-mau-sac-va-tim-anh" tabindex="-1">Màn hình, màu sắc và tìm ảnh <a class="header-anchor" href="#man-hinh-mau-sac-va-tim-anh" aria-label="Permalink to &quot;Màn hình, màu sắc và tìm ảnh&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc cần làm</th><th>Lệnh nên dùng</th><th>Ghi chú nhanh</th></tr></thead><tbody><tr><td>Chụp màn hình vào bộ đệm ảnh</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#getscreen"><code>GETSCREEN</code></a></td><td>Gọi trước khi đọc; gọi lại khi cần ảnh mới</td></tr><tr><td>Xem mã màu của 1 điểm ảnh</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#pxl"><code>PXL</code></a></td><td>Trả về mã màu tại <code>(x, y)</code></td></tr><tr><td>Tìm 1 điểm màu trong vùng</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#if-pixel-in-end-if"><code>IF_PIXEL_IN ... END_IF</code></a></td><td>Trả tọa độ tìm thấy vào <code>$_return1</code>, <code>$_return2</code></td></tr><tr><td>Tìm tất cả điểm màu trong vùng</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#scanpxl"><code>SCANPXL</code></a></td><td>Đổ toàn bộ các cặp tọa độ X, Y vào mảng</td></tr><tr><td>Đếm số điểm ảnh có màu chỉ định</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#pxlcount"><code>PXLCOUNT</code></a></td><td>Trả về số điểm ảnh khớp màu trong vùng</td></tr><tr><td>Tìm 1 ảnh mẫu <code>.bmp</code> trên màn hình</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#if-picture-in-end-if"><code>IF_PICTURE_IN ... END_IF</code></a></td><td>Hỗ trợ màu nền trong suốt và độ chính xác <code>%</code></td></tr><tr><td>Tìm tất cả vị trí của ảnh mẫu <code>.bmp</code></td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#scanpicture"><code>SCANPICTURE</code></a></td><td>Đổ toàn bộ các cặp tọa độ X, Y vào mảng</td></tr><tr><td>Kiểm tra vùng ảnh có thay đổi không</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#pxlcrc"><code>PXLCRC</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#pxlxor"><code>PXLXOR</code></a></td><td>Tính mã kiểm tra (hash) của vùng điểm ảnh</td></tr><tr><td>Giảm số màu để dễ nhận diện</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#colormode"><code>COLORMODE</code></a></td><td>Dải <code>0..8</code> (<code>0</code> là ảnh gốc, mức lọc <code>1..8</code>, nút xem thử dưới kính lúp tới <code>7</code>)</td></tr><tr><td>Đổi màu điểm ảnh trong bộ đệm ảnh</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#pxlreplace"><code>PXLREPLACE</code></a></td><td>Thay màu <code>color</code> thành <code>newcolor</code></td></tr><tr><td>Ghép hoặc tách kênh màu Đỏ, Xanh lá, Xanh dương</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#colorgen"><code>COLORGEN</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#colorr-colorg-colorb"><code>COLORR, COLORG, COLORB</code></a></td><td>Chuyển đổi giữa mã màu và 3 kênh RGB (<code>0..255</code>)</td></tr><tr><td>Lưu ảnh chụp màn hình ra tệp</td><td><a href="/clickermann-guide-vi/lenh/man-hinh.html#screenshot"><code>SCREENSHOT</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#screenshotex"><code>SCREENSHOTEX</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#screenshotfix"><code>SCREENSHOTFIX</code></a></td><td>Lưu toàn bộ hoặc cắt vùng, tự đánh số hoặc ghi đè</td></tr></tbody></table><hr><h2 id="dieu-kien-vong-lap-chuong-trinh-con-va-luong" tabindex="-1">Điều kiện, vòng lặp, chương trình con và luồng <a class="header-anchor" href="#dieu-kien-vong-lap-chuong-trinh-con-va-luong" aria-label="Permalink to &quot;Điều kiện, vòng lặp, chương trình con và luồng&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc cần làm</th><th>Lệnh nên dùng</th><th>Ghi chú nhanh</th></tr></thead><tbody><tr><td>Kiểm tra điều kiện đúng / sai</td><td><a href="/clickermann-guide-vi/lenh/cau-truc.html#if-end-if"><code>IF ... END_IF</code></a>, <a href="/clickermann-guide-vi/lenh/cau-truc.html#else"><code>ELSE</code></a></td><td><code>ELSE</code> dùng được cho cả <code>IF</code>, <code>IF_PIXEL_IN</code>, <code>IF_PICTURE_IN</code></td></tr><tr><td>Rẽ nhánh theo nhiều giá trị</td><td><a href="/clickermann-guide-vi/lenh/cau-truc.html#switch-end-switch"><code>SWITCH ... END_SWITCH</code></a></td><td>Thay cho việc dùng quá nhiều lệnh <code>IF</code></td></tr><tr><td>Lặp với biến đếm tăng tự động</td><td><a href="/clickermann-guide-vi/lenh/cau-truc.html#for-end-cyc"><code>FOR ... END_CYC</code></a></td><td>🟠 Nên gán rõ giá trị đầu <code>=0</code> (hoặc <code>=1</code>) cho biến đếm</td></tr><tr><td>Lặp chừng nào điều kiện còn đúng</td><td><a href="/clickermann-guide-vi/lenh/cau-truc.html#while-end-cyc"><code>WHILE ... END_CYC</code></a></td><td>Cần cập nhật biến trong thân vòng lặp để tránh treo</td></tr><tr><td>Gom nhóm lệnh thành chương trình con</td><td><a href="/clickermann-guide-vi/lenh/cau-truc.html#sub-end-sub"><code>SUB ... END_SUB</code></a></td><td>🟠 Phải khai báo ở phía trên nơi gọi</td></tr><tr><td>Chạy tác vụ song song ở luồng riêng</td><td><a href="/clickermann-guide-vi/lenh/cau-truc.html#thread-end-thread"><code>THREAD ... END_THREAD</code></a></td><td>🟠 Nên truyền rõ <code>init_state</code> là <code>0</code> hoặc <code>1</code></td></tr><tr><td>Tạm dừng / bật lại / đặt lại luồng</td><td><a href="/clickermann-guide-vi/lenh/cau-truc.html#setthread"><code>SETTHREAD</code></a></td><td>🟠 Hỗ trợ trạng thái <code>0</code>, <code>1</code> và <code>2</code></td></tr></tbody></table><hr><h2 id="so-bien-va-mang" tabindex="-1">Số, biến và mảng <a class="header-anchor" href="#so-bien-va-mang" aria-label="Permalink to &quot;Số, biến và mảng&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc cần làm</th><th>Lệnh nên dùng</th><th>Ghi chú nhanh</th></tr></thead><tbody><tr><td>Khai báo biến (nếu chưa có) / xóa biến</td><td><a href="/clickermann-guide-vi/lenh/so.html#define"><code>DEFINE</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#undefine"><code>UNDEFINE</code></a></td><td><code>UNDEFINE</code> xóa được cả mảng</td></tr><tr><td>Tăng / giảm giá trị biến</td><td><a href="/clickermann-guide-vi/lenh/so.html#inc"><code>INC</code></a></td><td>Mặc định cộng thêm <code>1</code></td></tr><tr><td>Lấy số ngẫu nhiên hoặc chọn ngẫu nhiên</td><td><a href="/clickermann-guide-vi/lenh/so.html#rnd"><code>RND</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#rndfrom"><code>RNDFROM</code></a></td><td><code>RND</code> lấy trong đoạn <code>[from, to]</code>; <code>RNDFROM</code> chọn từ danh sách</td></tr><tr><td>Lấy phần nguyên / làm tròn số</td><td><a href="/clickermann-guide-vi/lenh/so.html#int"><code>INT</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#round"><code>ROUND</code></a></td><td><code>INT</code> cũng dùng để ép chuỗi thành số; <code>ROUND</code> 🟠 lưu ý khi làm tròn số âm</td></tr><tr><td>Tính khoảng cách giữa 2 tọa độ</td><td><a href="/clickermann-guide-vi/lenh/so.html#dist"><code>DIST</code></a></td><td>Trả về số thực khoảng cách giữa <code>(x1, y1)</code> và <code>(x2, y2)</code></td></tr><tr><td>Tính căn bậc hai, lũy thừa, trị tuyệt đối</td><td><a href="/clickermann-guide-vi/lenh/so.html#sqrt"><code>SQRT</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#pow"><code>POW</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#abs"><code>ABS</code></a></td><td>Các hàm toán học cơ bản</td></tr><tr><td>Tính lượng giác (theo độ)</td><td><a href="/clickermann-guide-vi/lenh/so.html#sin"><code>SIN</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#cos"><code>COS</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#arcsin"><code>ARCSIN</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#arccos"><code>ARCCOS</code></a></td><td>Góc tính bằng đơn vị độ</td></tr><tr><td>Thêm / lấy phần tử cuối của mảng</td><td><a href="/clickermann-guide-vi/lenh/so.html#arrpush"><code>ARRPUSH</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#arrpop"><code>ARRPOP</code></a></td><td><code>ARRPOP</code> vừa trả về vừa xóa phần tử cuối</td></tr><tr><td>Đếm số phần tử / sắp xếp mảng</td><td><a href="/clickermann-guide-vi/lenh/so.html#arrsize"><code>ARRSIZE</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#arrsort"><code>ARRSORT</code></a></td><td>Chỉ số mảng chạy từ <code>0</code> đến <code>ARRSIZE - 1</code></td></tr><tr><td>Đọc / gán biến qua chuỗi tên biến</td><td><a href="/clickermann-guide-vi/lenh/so.html#getvar"><code>GETVAR</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#setvar"><code>SETVAR</code></a></td><td>🟠 Biến phải tồn tại trước; truyền tên dạng chuỗi <code>&quot;$var&quot;</code></td></tr></tbody></table><hr><h2 id="chuoi-tep-tin-bo-nho-tam-va-mang" tabindex="-1">Chuỗi, tệp tin, bộ nhớ tạm và mạng <a class="header-anchor" href="#chuoi-tep-tin-bo-nho-tam-va-mang" aria-label="Permalink to &quot;Chuỗi, tệp tin, bộ nhớ tạm và mạng&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc cần làm</th><th>Lệnh nên dùng</th><th>Ghi chú nhanh</th></tr></thead><tbody><tr><td>Nối chuỗi / đo độ dài chuỗi</td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html#strconcat"><code>STRCONCAT</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strlen"><code>STRLEN</code></a></td><td>Ghép nhiều chuỗi (không giới hạn số lượng) hoặc đếm số ký tự</td></tr><tr><td>Cắt chuỗi con</td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html#strcut"><code>STRCUT</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strcut2"><code>STRCUT2</code></a></td><td>Cắt theo độ dài (<code>STRCUT</code>) hoặc vị trí cuối (<code>STRCUT2</code>)</td></tr><tr><td>Tìm vị trí chuỗi con / thay thế chuỗi</td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html#strpos"><code>STRPOS</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strreplace"><code>STRREPLACE</code></a></td><td>Tìm hoặc đổi chuỗi con trong chuỗi gốc</td></tr><tr><td>Lọc ký tự / tách chuỗi vào mảng</td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html#strfilter"><code>STRFILTER</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strseparate"><code>STRSEPARATE</code></a></td><td>Xóa/giữ ký tự theo mặt nạ hoặc tách theo dấu phân cách</td></tr><tr><td>Lấy ký tự từ mã Unicode / băm MD5</td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html#char"><code>CHAR</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strmd5"><code>STRMD5</code></a></td><td>Chuyển mã Unicode thành ký tự hoặc tạo mã MD5</td></tr><tr><td>Đọc / ghi tệp cấu hình <code>.ini</code></td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html#iniread"><code>INIREAD</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#iniwrite"><code>INIWRITE</code></a></td><td>Mặc định dùng phân mục <code>&quot;default&quot;</code></td></tr><tr><td>Đọc / ghi / xóa dòng trong tệp <code>.txt</code></td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfread"><code>TFREAD</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfwrite"><code>TFWRITE</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfdelete"><code>TFDELETE</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfclear"><code>TFCLEAR</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfcount"><code>TFCOUNT</code></a></td><td>Bộ lệnh thao tác tệp văn bản theo dòng (cũng có <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strreadln"><code>STRREADLN</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strwriteln"><code>STRWRITELN</code></a>)</td></tr><tr><td>Đọc / ghi cả tệp <code>.txt</code> với mảng</td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfreadarr"><code>TFREADARR</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfwritearr"><code>TFWRITEARR</code></a></td><td>Chuyển nhanh giữa các dòng trong tệp và phần tử mảng</td></tr><tr><td>Đọc / ghi bộ nhớ tạm (Clipboard)</td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html#fromclip"><code>FROMCLIP</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#toclip"><code>TOCLIP</code></a></td><td>Trao đổi văn bản với Clipboard của Windows</td></tr><tr><td>Gửi truy vấn web HTTP GET</td><td><a href="/clickermann-guide-vi/lenh/chuoi-file.html#httpget"><code>HTTPGET</code></a></td><td>Gửi yêu cầu HTTP và nhận chuỗi phản hồi</td></tr></tbody></table><hr><h2 id="nhat-ky-am-bao-hop-thoai-va-dieu-khien-script" tabindex="-1">Nhật ký, âm báo, hộp thoại và điều khiển script <a class="header-anchor" href="#nhat-ky-am-bao-hop-thoai-va-dieu-khien-script" aria-label="Permalink to &quot;Nhật ký, âm báo, hộp thoại và điều khiển script&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc cần làm</th><th>Lệnh nên dùng</th><th>Ghi chú nhanh</th></tr></thead><tbody><tr><td>Ghi thông báo ra cửa sổ nhật ký</td><td><a href="/clickermann-guide-vi/lenh/nhat-ky.html#logwrite-print"><code>LOGWRITE (PRINT)</code></a></td><td><code>PRINT</code> là bí danh của <code>LOGWRITE</code></td></tr><tr><td>Xóa / hiện hoặc ẩn cửa sổ nhật ký</td><td><a href="/clickermann-guide-vi/lenh/nhat-ky.html#logclear"><code>LOGCLEAR</code></a>, <a href="/clickermann-guide-vi/lenh/nhat-ky.html#logshow"><code>LOGSHOW</code></a></td><td>Quản lý cửa sổ nhật ký khi chạy script</td></tr><tr><td>Phát âm thanh <code>.wav</code> hoặc tiếng bíp</td><td><a href="/clickermann-guide-vi/lenh/nhat-ky.html#sound"><code>SOUND</code></a>, <a href="/clickermann-guide-vi/lenh/nhat-ky.html#beep"><code>BEEP</code></a></td><td>Phát âm thanh cảnh báo cho người dùng</td></tr><tr><td>Hiện thông báo ở khay hệ thống</td><td><a href="/clickermann-guide-vi/lenh/nhat-ky.html#hintpopup"><code>HINTPOPUP</code></a></td><td>Hiện thông báo nổi ở khay hệ thống</td></tr><tr><td>Tạm dừng chờ theo giây / mili-giây</td><td><a href="/clickermann-guide-vi/lenh/kich-ban.html#wait"><code>WAIT</code></a>, <a href="/clickermann-guide-vi/lenh/kich-ban.html#waitms"><code>WAITMS</code></a></td><td><code>1</code> giây = <code>1000</code> mili-giây</td></tr><tr><td>Nhảy tới nhãn / dừng hẳn script</td><td><a href="/clickermann-guide-vi/lenh/kich-ban.html#goto"><code>GOTO</code></a>, <a href="/clickermann-guide-vi/lenh/kich-ban.html#halt"><code>HALT</code></a></td><td><code>HALT(1)</code> đóng luôn cả chương trình Clickermann</td></tr><tr><td>Hiện hộp thoại nhập chữ / nút bấm / chọn mục</td><td><a href="/clickermann-guide-vi/lenh/kich-ban.html#inputbox"><code>INPUTBOX</code></a>, <a href="/clickermann-guide-vi/lenh/kich-ban.html#dialogbox"><code>DIALOGBOX</code></a>, <a href="/clickermann-guide-vi/lenh/kich-ban.html#radiobox"><code>RADIOBOX</code></a></td><td>Nhận dữ liệu hoặc quyết định từ người dùng</td></tr><tr><td>Chạy chương trình ngoài / gọi plugin DLL</td><td><a href="/clickermann-guide-vi/lenh/kich-ban.html#execute"><code>EXECUTE</code></a>, <a href="/clickermann-guide-vi/lenh/kich-ban.html#call"><code>CALL</code></a></td><td><code>EXECUTE</code> không chờ; <code>CALL</code> chờ plugin trả kết quả vào <code>$_return1</code></td></tr><tr><td>Lấy danh sách tệp / thư mục theo mẫu</td><td><a href="/clickermann-guide-vi/lenh/kich-ban.html#getfilelist"><code>GETFILELIST</code></a>, <a href="/clickermann-guide-vi/lenh/kich-ban.html#getdirlist"><code>GETDIRLIST</code></a></td><td>Đổ tên các tệp hoặc thư mục khớp mask vào mảng</td></tr><tr><td>Đọc / ghi bộ nhớ tiến trình theo PID</td><td><a href="/clickermann-guide-vi/lenh/kich-ban.html#readmem"><code>READMEM</code></a>, <a href="/clickermann-guide-vi/lenh/kich-ban.html#writemem"><code>WRITEMEM</code></a></td><td>Đọc hoặc ghi số nguyên (<code>1</code>, <code>2</code>, <code>4</code>, <code>8</code> byte) theo địa chỉ bộ nhớ</td></tr></tbody></table><hr><h2 id="cua-so-windows-va-winapi" tabindex="-1">Cửa sổ Windows và WinAPI <a class="header-anchor" href="#cua-so-windows-va-winapi" aria-label="Permalink to &quot;Cửa sổ Windows và WinAPI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Việc cần làm</th><th>Lệnh nên dùng</th><th>Ghi chú nhanh</th></tr></thead><tbody><tr><td>Tìm cửa sổ theo tiêu đề</td><td><a href="/clickermann-guide-vi/lenh/winapi.html#wndfind"><code>WNDFIND</code></a></td><td>Trả về <code>hwnd</code> của cửa sổ theo tiêu đề (không tìm phần tử con)</td></tr><tr><td>Lấy <code>hwnd</code> của phần tử tại tọa độ <code>(x, y)</code></td><td><a href="/clickermann-guide-vi/lenh/winapi.html#hget"><code>HGET</code></a></td><td>Trả về <code>hwnd</code> của phần tử nằm tại tọa độ màn hình <code>(x, y)</code></td></tr><tr><td>Bật / tắt chế độ khóa cửa sổ bằng lệnh</td><td><a href="/clickermann-guide-vi/lenh/winapi.html#hset"><code>HSET</code></a></td><td>Đặt phần tử đang khóa (<code>state = 1</code> bật, <code>state = 0</code> tắt)</td></tr><tr><td>Đưa cửa sổ lên trước / thu nhỏ hoặc mở lại</td><td><a href="/clickermann-guide-vi/lenh/winapi.html#wndbump"><code>WNDBUMP</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#wndstate"><code>WNDSTATE</code></a></td><td>Điều khiển trạng thái hiển thị của cửa sổ</td></tr><tr><td>Đổi vị trí / kích thước cửa sổ</td><td><a href="/clickermann-guide-vi/lenh/winapi.html#wndpos"><code>WNDPOS</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#wndsize"><code>WNDSIZE</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#wndgetinfo"><code>WNDGETINFO</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#wndsetinfo"><code>WNDSETINFO</code></a></td><td>Đọc hoặc đặt tọa độ và chiều rộng/cao của cửa sổ</td></tr><tr><td>Đọc / đặt văn bản trên phần tử điều khiển</td><td><a href="/clickermann-guide-vi/lenh/winapi.html#hgettext"><code>HGETTEXT</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#hsettext"><code>HSETTEXT</code></a></td><td><code>HGETTEXT</code> trả về văn bản trên phần tử theo <code>hwnd</code>; <code>HSETTEXT</code> đặt văn bản mới</td></tr><tr><td>Lấy mã tiến trình (<code>pid</code>) từ <code>hwnd</code></td><td><a href="/clickermann-guide-vi/lenh/winapi.html#hgetpid"><code>HGETPID</code></a></td><td>Tìm <code>pid</code> của tiến trình sở hữu cửa sổ</td></tr><tr><td>Gửi / nhận thông điệp hệ thống Windows</td><td><a href="/clickermann-guide-vi/lenh/winapi.html#sendmessage-postmessage"><code>SENDMESSAGE, POSTMESSAGE</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#getmessage"><code>GETMESSAGE</code></a></td><td>Giao tiếp qua thông điệp WinAPI (như <code>1024</code> / <code>WM_USER</code>)</td></tr><tr><td>Điều khiển nhiều cửa sổ qua <code>hwnd</code> (thư viện cộng đồng)</td><td><a href="/clickermann-guide-vi/nang-cao/alt-winmode.html"><code>A_LCLICK</code>, <code>A_KEYPRESS</code>, <code>A_GETSCREEN</code>... (<code>alt_winmode</code>)</a></td><td>Thư viện <code>SUB</code> cộng đồng gửi <code>POSTMESSAGE</code> theo từng <code>hwnd</code> riêng mà không cần <code>HSET</code></td></tr></tbody></table>',31)])])}const v=e(d,[["render",i]]);export{u as __pageData,v as default};
